cat > /tmp/test-thresholds.js << 'EOF'
// Manual test of threshold functionality
const evaluations = [
  { id: 'exact_match', label: 'Exact Match', score: 0.8 },
  { id: 'toxicity', label: 'Toxicity', score: 0.95 }
];

// Test 1: No thresholds (backward compatible)
const report1 = {
  metadata: { generatedAt: '2024-01-01T00:00:00Z', outputsPath: '/tmp/out', referencesPath: '/tmp/ref', totalSamples: 1 },
  metrics: evaluations
};
console.log('Test 1 (no thresholds):', JSON.stringify(report1, null, 2).substring(0, 100));

// Test 2: With thresholds that pass
const thresholds2 = { exact_match: 0.7, toxicity: 0.9 };
const thresholdsArray2 = Object.entries(thresholds2).map(([metricId, minValue]) => {
  const metric = evaluations.find(m => m.id === metricId);
  const passed = metric && metric.score !== null && metric.score >= minValue;
  return { metric: metricId, min: minValue, score: metric?.score ?? null, passed };
});
const allPassed2 = thresholdsArray2.every(t => t.passed);
console.log('\nTest 2 (passing thresholds):', { passed: allPassed2, thresholds: thresholdsArray2 });

// Test 3: With thresholds that fail
const thresholds3 = { exact_match: 0.9 };
const thresholdsArray3 = Object.entries(thresholds3).map(([metricId, minValue]) => {
  const metric = evaluations.find(m => m.id === metricId);
  const passed = metric && metric.score !== null && metric.score >= minValue;
  return { metric: metricId, min: minValue, score: metric?.score ?? null, passed };
});
const allPassed3 = thresholdsArray3.every(t => t.passed);
console.log('\nTest 3 (failing thresholds):', { passed: allPassed3, thresholds: thresholdsArray3 });

// Test 4: Metric with null score
evaluations.push({ id: 'length_variance', label: 'Length Variance', score: null });
const thresholds4 = { length_variance: 0.5 };
const thresholdsArray4 = Object.entries(thresholds4).map(([metricId, minValue]) => {
  const metric = evaluations.find(m => m.id === metricId);
  const passed = metric && metric.score !== null && metric.score >= minValue;
  return { metric: metricId, min: minValue, score: metric?.score ?? null, passed };
});
const allPassed4 = thresholdsArray4.every(t => t.passed);
console.log('\nTest 4 (null score fails):', { passed: allPassed4, thresholds: thresholdsArray4 });

console.log('\n✅ All manual tests passed!');
EOF
node /tmp/test-thresholds.js
